function sharedValues(a: number[], b: number[]): number[] {
  const x = [...a].sort((p, q) => p - q), y = [...b].sort((p, q) => p - q);
  const out: number[] = [];
  let i = 0, j = 0;
  while (i < x.length && j < y.length) {
    if (x[i] < y[j]) i++;
    else if (x[i] > y[j]) j++;
    else {
      if (out.length === 0 || out[out.length - 1] !== x[i]) out.push(x[i]);
      i++; j++;
    }
  }
  return out;
}

