class Solution:
    def sharedValues(self, a: List[int], b: List[int]) -> List[int]:
        x, y = sorted(a), sorted(b)
        out, i, j = [], 0, 0
        while i < len(x) and j < len(y):
            if x[i] < y[j]:
                i += 1
            elif x[i] > y[j]:
                j += 1
            else:
                if not out or out[-1] != x[i]:
                    out.append(x[i])
                i += 1
                j += 1
        return out

